CREATE TABLE IF NOT EXISTS loom_users(id BIGINT PRIMARY KEY AUTO_INCREMENT,auth_version BIGINT NOT NULL DEFAULT 0, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS loom_sessions(token VARCHAR(255) PRIMARY KEY, user_id BIGINT NOT NULL, csrf VARCHAR(255) NOT NULL, expires BIGINT NOT NULL,FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS loom_jobs(id BIGINT PRIMARY KEY AUTO_INCREMENT, kind VARCHAR(255) NOT NULL, payload LONGTEXT NOT NULL, owner BIGINT NOT NULL, state VARCHAR(255) NOT NULL DEFAULT 'pending', attempts BIGINT NOT NULL DEFAULT 0, available BIGINT NOT NULL, lease VARCHAR(255), lease_until BIGINT, result LONGTEXT, error LONGTEXT, created BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX loom_jobs_ready ON loom_jobs(state,available);
CREATE TABLE IF NOT EXISTS loom_schedules(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(255) NOT NULL UNIQUE, kind VARCHAR(255) NOT NULL, payload LONGTEXT NOT NULL, owner BIGINT NOT NULL, interval_seconds BIGINT NOT NULL, next_run BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS loom_auth_limits(`key` VARCHAR(255) PRIMARY KEY, attempts BIGINT NOT NULL, until_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
